script.setup:
// WaveFunctionCollapse (kchapelier's JS port of mxgmn's algorithm) solves a grid of tiles live.
// Each tileset is drawn here with canvas 2D; its adjacency rules come from edge sockets, and the
// library's SimpleTiledModel observes the lowest-entropy cell and propagates, a few steps a frame.
// Unsolved cells show the library's superposition (the average of the tiles still possible)
// and an entropy marker that shrinks and heats up as the options run out.
const mod = await ctx.utils.import("https://esm.sh/wavefunctioncollapse@2.1.0");
const wfc = mod.SimpleTiledModel ? mod : (mod.default ?? mod);
const gl = ctx.gl;

// Sockets are listed [right, top, left, bottom]. Symmetry letters follow mxgmn's convention:
// X none, I two rotations, \ two (diagonal), L and T four. Rotation r of a tile is turned
// counter-clockwise r times, exactly as the library rotates its bitmaps.
const TAU = Math.PI * 2;
const tube = (g, draw, w, fill, edge) => {
  g.lineCap = "butt";
  g.strokeStyle = edge; g.lineWidth = w + 0.08; g.beginPath(); draw(); g.stroke();
  g.strokeStyle = fill; g.lineWidth = w; g.beginPath(); draw(); g.stroke();
  g.strokeStyle = "rgba(255,255,255,0.28)"; g.lineWidth = w * 0.22; g.beginPath(); draw(); g.stroke();
};
const KNOTS = {
  bg: "#0d1020",
  base(g) { g.fillStyle = "#0d1020"; g.fillRect(0, 0, 1, 1); },
  tiles: [
    { name: "empty", sym: "X", w: 1.2, s: [0, 0, 0, 0], draw(g) {
      g.fillStyle = "rgba(140,150,255,0.25)"; g.beginPath(); g.arc(0.5, 0.5, 0.035, 0, TAU); g.fill(); } },
    { name: "line", sym: "I", w: 1.6, s: [1, 0, 1, 0], draw(g, c) { tube(g, () => { g.moveTo(0, 0.5); g.lineTo(1, 0.5); }, 0.26, c[0], c[2]); } },
    { name: "bend", sym: "L", w: 2.2, s: [1, 1, 0, 0], draw(g, c) { tube(g, () => g.arc(1, 0, 0.5, Math.PI / 2, Math.PI), 0.26, c[1], c[2]); } },
    { name: "cross", sym: "I", w: 0.9, s: [1, 1, 1, 1], draw(g, c) {
      tube(g, () => { g.moveTo(0.5, 0); g.lineTo(0.5, 1); }, 0.26, c[0], c[2]);
      tube(g, () => { g.moveTo(0, 0.5); g.lineTo(1, 0.5); }, 0.26, c[1], c[2]); } },
    { name: "double", sym: "\\", w: 1.4, s: [1, 1, 1, 1], draw(g, c) {
      tube(g, () => g.arc(1, 0, 0.5, Math.PI / 2, Math.PI), 0.26, c[1], c[2]);
      tube(g, () => g.arc(0, 1, 0.5, -Math.PI / 2, 0), 0.26, c[0], c[2]); } },
    { name: "cap", sym: "T", w: 0.25, s: [0, 0, 0, 1], draw(g, c) {
      tube(g, () => { g.moveTo(0.5, 1); g.lineTo(0.5, 0.55); }, 0.26, c[0], c[2]);
      g.fillStyle = c[2]; g.beginPath(); g.arc(0.5, 0.52, 0.2, 0, TAU); g.fill();
      g.fillStyle = c[1]; g.beginPath(); g.arc(0.5, 0.52, 0.16, 0, TAU); g.fill(); } },
  ],
  colors: ["#f4f1ea", "#ffffff", "#07060c"],
  tint: 1,
};
const trace = (g, draw, w = 0.12) => {
  g.lineCap = "round"; g.lineJoin = "round";
  g.strokeStyle = "rgba(255,190,80,0.18)"; g.lineWidth = w * 2.6; g.beginPath(); draw(); g.stroke();
  g.strokeStyle = "#e9a83c"; g.lineWidth = w; g.beginPath(); draw(); g.stroke();
  g.strokeStyle = "#ffe6a8"; g.lineWidth = w * 0.3; g.beginPath(); draw(); g.stroke();
};
const pad = (g, x, y, r) => {
  g.fillStyle = "#e9a83c"; g.beginPath(); g.arc(x, y, r, 0, TAU); g.fill();
  g.fillStyle = "#0b2a22"; g.beginPath(); g.arc(x, y, r * 0.45, 0, TAU); g.fill();
};
const CIRCUIT = {
  base(g) {
    g.fillStyle = "#0b2a22"; g.fillRect(0, 0, 1, 1);
    g.fillStyle = "rgba(90,220,170,0.10)";
    for (let i = 0; i < 4; i++) for (let j = 0; j < 4; j++) g.fillRect(0.11 + i * 0.25, 0.11 + j * 0.25, 0.03, 0.03);
  },
  tiles: [
    { name: "board", sym: "X", w: 3, s: [0, 0, 0, 0], draw() {} },
    { name: "trace", sym: "I", w: 2.2, s: [1, 0, 1, 0], draw(g) { trace(g, () => { g.moveTo(-0.1, 0.5); g.lineTo(1.1, 0.5); }); } },
    { name: "corner", sym: "L", w: 2, s: [1, 1, 0, 0], draw(g) { trace(g, () => { g.moveTo(1.1, 0.5); g.lineTo(0.75, 0.5); g.lineTo(0.5, 0.25); g.lineTo(0.5, -0.1); }); } },
    { name: "tee", sym: "T", w: 0.5, s: [1, 0, 1, 1], draw(g) {
      trace(g, () => { g.moveTo(-0.1, 0.5); g.lineTo(1.1, 0.5); g.moveTo(0.5, 0.5); g.lineTo(0.5, 1.1); });
      g.fillStyle = "#ffe6a8"; g.beginPath(); g.arc(0.5, 0.5, 0.09, 0, TAU); g.fill(); } },
    { name: "via", sym: "T", w: 0.5, s: [0, 0, 0, 1], draw(g) { trace(g, () => { g.moveTo(0.5, 1.1); g.lineTo(0.5, 0.5); }); pad(g, 0.5, 0.45, 0.17); } },
    { name: "chip", sym: "X", w: 0.25, s: [1, 1, 1, 1], draw(g) {
      trace(g, () => { g.moveTo(-0.1, 0.5); g.lineTo(1.1, 0.5); g.moveTo(0.5, -0.1); g.lineTo(0.5, 1.1); });
      g.fillStyle = "#c9ced6";
      for (let k = 0; k < 3; k++) { const o = 0.3 + k * 0.2; g.fillRect(o - 0.03, 0.14, 0.06, 0.72); g.fillRect(0.14, o - 0.03, 0.72, 0.06); }
      g.fillStyle = "#15171c"; g.fillRect(0.22, 0.22, 0.56, 0.56);
      g.strokeStyle = "#3a3f4a"; g.lineWidth = 0.02; g.strokeRect(0.25, 0.25, 0.5, 0.5);
      g.fillStyle = "#3a3f4a"; g.beginPath(); g.arc(0.31, 0.31, 0.03, 0, TAU); g.fill(); } },
    { name: "resistor", sym: "I", w: 0.5, s: [1, 0, 1, 0], draw(g) {
      trace(g, () => { g.moveTo(-0.1, 0.5); g.lineTo(1.1, 0.5); });
      g.fillStyle = "#d8c7a0"; g.beginPath(); g.roundRect(0.24, 0.38, 0.52, 0.24, 0.1); g.fill();
      ["#7a3b1e", "#111", "#d13b2a", "#c8a03a"].forEach((c, k) => { g.fillStyle = c; g.fillRect(0.32 + k * 0.1, 0.38, 0.05, 0.24); }); } },
    { name: "swerve", sym: "\\", w: 0.6, s: [1, 1, 1, 1], draw(g) {
      trace(g, () => { g.moveTo(1.1, 0.5); g.lineTo(0.8, 0.5); g.lineTo(0.5, 0.2); g.lineTo(0.5, -0.1); });
      trace(g, () => { g.moveTo(-0.1, 0.5); g.lineTo(0.2, 0.5); g.lineTo(0.5, 0.8); g.lineTo(0.5, 1.1); }); } },
  ],
};
// Rivers: 0 grass, 1 water, 2 road. Sockets are symmetric, so rotations match edge to edge.
const water = (g, draw) => {
  g.lineCap = "butt";
  g.strokeStyle = "#d8c98f"; g.lineWidth = 0.46; g.beginPath(); draw(); g.stroke();
  g.strokeStyle = "#2f7fb5"; g.lineWidth = 0.36; g.beginPath(); draw(); g.stroke();
  g.strokeStyle = "#5fb4e0"; g.lineWidth = 0.16; g.beginPath(); draw(); g.stroke();
};
const road = (g, draw) => {
  g.lineCap = "butt";
  g.strokeStyle = "#8a7656"; g.lineWidth = 0.24; g.beginPath(); draw(); g.stroke();
  g.strokeStyle = "#c9b48a"; g.lineWidth = 0.18; g.beginPath(); draw(); g.stroke();
};
const tree = (g, x, y, r) => {
  g.fillStyle = "rgba(20,50,20,0.35)"; g.beginPath(); g.arc(x + r * 0.25, y + r * 0.3, r, 0, TAU); g.fill();
  g.fillStyle = "#2f6b2f"; g.beginPath(); g.arc(x, y, r, 0, TAU); g.fill();
  g.fillStyle = "#4f9a3e"; g.beginPath(); g.arc(x - r * 0.3, y - r * 0.3, r * 0.5, 0, TAU); g.fill();
};
const RIVERS = {
  base(g) {
    g.fillStyle = "#79b45a"; g.fillRect(0, 0, 1, 1);
    g.fillStyle = "rgba(255,255,200,0.10)"; g.fillRect(0.1, 0.2, 0.05, 0.02); g.fillRect(0.7, 0.75, 0.05, 0.02); g.fillRect(0.6, 0.15, 0.04, 0.02);
  },
  tiles: [
    { name: "grass", sym: "X", w: 5, s: [0, 0, 0, 0], draw() {} },
    { name: "forest", sym: "X", w: 1.6, s: [0, 0, 0, 0], draw(g) { tree(g, 0.3, 0.32, 0.17); tree(g, 0.72, 0.45, 0.2); tree(g, 0.38, 0.75, 0.15); } },
    { name: "river", sym: "I", w: 1.6, s: [1, 0, 1, 0], draw(g) { water(g, () => { g.moveTo(-0.1, 0.5); g.lineTo(1.1, 0.5); }); } },
    { name: "bend", sym: "L", w: 1.4, s: [1, 1, 0, 0], draw(g) { water(g, () => g.arc(1, 0, 0.5, Math.PI / 2, Math.PI)); } },
    { name: "lake", sym: "T", w: 0.2, s: [0, 0, 0, 1], draw(g) {
      water(g, () => { g.moveTo(0.5, 1.1); g.lineTo(0.5, 0.6); });
      g.fillStyle = "#d8c98f"; g.beginPath(); g.ellipse(0.5, 0.45, 0.38, 0.3, 0, 0, TAU); g.fill();
      g.fillStyle = "#2f7fb5"; g.beginPath(); g.ellipse(0.5, 0.45, 0.33, 0.25, 0, 0, TAU); g.fill();
      g.fillStyle = "#5fb4e0"; g.beginPath(); g.ellipse(0.45, 0.4, 0.18, 0.1, 0, 0, TAU); g.fill(); } },
    { name: "road", sym: "I", w: 1.2, s: [2, 0, 2, 0], draw(g) { road(g, () => { g.moveTo(-0.1, 0.5); g.lineTo(1.1, 0.5); }); } },
    { name: "turn", sym: "L", w: 1, s: [2, 2, 0, 0], draw(g) { road(g, () => g.arc(1, 0, 0.5, Math.PI / 2, Math.PI)); } },
    { name: "fork", sym: "T", w: 0.3, s: [2, 0, 2, 2], draw(g) { road(g, () => { g.moveTo(-0.1, 0.5); g.lineTo(1.1, 0.5); g.moveTo(0.5, 0.5); g.lineTo(0.5, 1.1); }); } },
    { name: "bridge", sym: "I", w: 0.6, s: [2, 1, 2, 1], draw(g) {
      water(g, () => { g.moveTo(0.5, -0.1); g.lineTo(0.5, 1.1); });
      g.fillStyle = "rgba(0,0,0,0.25)"; g.fillRect(0, 0.38, 1, 0.3);
      g.fillStyle = "#9a6a3a"; g.fillRect(0, 0.36, 1, 0.28);
      g.fillStyle = "#c08850"; for (let k = 0; k < 6; k++) g.fillRect(0.02 + k * 0.165, 0.38, 0.13, 0.24); } },
    { name: "house", sym: "T", w: 0.35, s: [0, 0, 0, 2], draw(g) {
      road(g, () => { g.moveTo(0.5, 1.1); g.lineTo(0.5, 0.6); });
      g.fillStyle = "rgba(0,0,0,0.3)"; g.fillRect(0.3, 0.3, 0.46, 0.38);
      g.fillStyle = "#efe4cf"; g.fillRect(0.26, 0.26, 0.46, 0.36);
      g.fillStyle = "#c2523b"; g.beginPath(); g.moveTo(0.22, 0.3); g.lineTo(0.49, 0.1); g.lineTo(0.76, 0.3); g.closePath(); g.fill();
      g.fillStyle = "#8e3a2a"; g.fillRect(0.45, 0.46, 0.08, 0.16); } },
  ],
};
const TILESETS = [KNOTS, CIRCUIT, RIVERS];
const CARD = { X: 1, I: 2, "\\": 2, L: 4, T: 4 };
const turn = (s, r) => { let o = s.slice(); for (let k = 0; k < r; k++) o = [o[3], o[0], o[1], o[2]]; return o; };

// One tile drawn into a square of S pixels, rotated r quarter turns counter-clockwise.
function paint(g, set, tile, r, x, y, S) {
  g.save(); g.translate(x, y); g.scale(S, S);
  g.beginPath(); g.rect(0, 0, 1, 1); g.clip();
  set.base(g);
  g.translate(0.5, 0.5); g.rotate(-r * Math.PI / 2); g.translate(-0.5, -0.5);
  tile.draw(g, set.colors ?? []);
  g.restore();
}

// Builds the library's data object (tiny bitmaps for its superposition view, neighbor rules
// from the sockets) plus a high-resolution atlas of every rotation for the final picture.
function buildSet(index, tilePx) {
  const set = TILESETS[index], small = 8;
  const variants = [];
  for (const tile of set.tiles) for (let r = 0; r < CARD[tile.sym]; r++) variants.push({ tile, r, s: turn(tile.s, r) });
  const scratch = new OffscreenCanvas(small, small), sg = scratch.getContext("2d", { willReadFrequently: true });
  const tiles = set.tiles.map((tile) => {
    sg.clearRect(0, 0, small, small); paint(sg, set, tile, 0, 0, 0, small);
    return { name: tile.name, symmetry: tile.sym, weight: tile.w, bitmap: Array.from(sg.getImageData(0, 0, small, small).data) };
  });
  const neighbors = [];
  for (const a of variants) for (const b of variants) {
    // a's right edge meets b's left edge.
    if (a.s[0] === b.s[2]) neighbors.push({ left: `${a.tile.name} ${a.r}`, right: `${b.tile.name} ${b.r}` });
  }
  const cols = 8, rows = Math.ceil(variants.length / cols);
  const atlas = new OffscreenCanvas(cols * tilePx, rows * tilePx), ag = atlas.getContext("2d");
  variants.forEach((v, t) => paint(ag, set, v.tile, v.r, (t % cols) * tilePx, Math.floor(t / cols) * tilePx, tilePx));
  return { data: { tilesize: small, tiles, neighbors }, atlas, tint: set.tint ?? 0, atlasCols: cols, atlasRows: rows, count: variants.length };
}

const tex = (filter) => {
  const t = gl.createTexture(); gl.bindTexture(gl.TEXTURE_2D, t);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, filter); gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, filter);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE); gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  return t;
};
const prog = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_cells, u_ghost, u_atlas;
uniform vec2 u_grid, u_origin, u_atlasGrid, u_res; uniform float u_cellPx, u_entropyOn, u_time, u_tint;
vec3 heat(float e){ // low entropy = hot
  return mix(mix(vec3(1.0, 0.95, 0.6), vec3(1.0, 0.35, 0.25), smoothstep(0.0, 0.45, e)), vec3(0.3, 0.45, 1.0), smoothstep(0.45, 1.0, e));
}
void main(){
  vec2 px = vec2(gl_FragCoord.x, u_res.y - gl_FragCoord.y) - u_origin;
  vec2 cell = floor(px / u_cellPx), f = px / u_cellPx - cell;
  if (cell.x < 0.0 || cell.y < 0.0 || cell.x >= u_grid.x || cell.y >= u_grid.y) { outColor = vec4(0.03, 0.03, 0.05, 1.0); return; }
  vec4 c = texelFetch(u_cells, ivec2(cell), 0);
  float tile = floor(c.r * 255.0 + 0.5), ent = c.g, age = c.b * 2.0;
  vec3 col;
  if (tile < 255.0) {
    // Pop in: the tile grows from 80% and flashes as it collapses.
    float pop = 1.0 - 0.25 * exp(-age * 16.0);
    vec2 q = (f - 0.5) / pop + 0.5;
    vec2 a = vec2(mod(tile, u_atlasGrid.x), floor(tile / u_atlasGrid.x));
    vec3 t = texture(u_atlas, (a + clamp(q, 0.5 / u_cellPx, 1.0 - 0.5 / u_cellPx)) / u_atlasGrid).rgb;
    col = (q.x < 0.0 || q.y < 0.0 || q.x > 1.0 || q.y > 1.0) ? vec3(0.03, 0.03, 0.05) : t;
    // Knots are drawn in white and colored here by a slow gradient across the grid.
    vec3 pal = 0.62 + 0.38 * cos(6.2832 * ((cell.x + cell.y) / (u_grid.x + u_grid.y) * 1.3 - u_time * 0.04 + vec3(0.0, 0.18, 0.4)));
    col = mix(col, col * pal, u_tint);
    col += vec3(1.0, 0.9, 0.7) * exp(-age * 14.0) * 0.35;
  } else {
    vec3 g = texture(u_ghost, (cell + f) / u_grid).rgb;
    col = g * 0.32 + 0.015;
    // Entropy marker: faint while every tile is still possible, brighter and hotter as the
    // neighbours' choices ban options, so the solving front glows.
    vec2 d = abs(f - 0.5);
    float k = 1.0 - ent;
    float box = max(d.x, d.y) - (0.07 + 0.16 * k);
    float m = smoothstep(0.025, 0.0, box) * (0.25 + 0.75 * k);
    float glow = exp(-max(box, 0.0) * 12.0) * k * k * 0.8;
    col = mix(col, heat(ent), m * u_entropyOn) + heat(ent) * glow * u_entropyOn;
    float grid = step(max(d.x, d.y), 0.47);
    col *= mix(0.6, 1.0, grid);
  }
  outColor = vec4(col, 1.0);
}`);
Object.assign(ctx.state, { wfc, buildSet, prog, cellTex: tex(gl.NEAREST), ghostTex: tex(gl.LINEAR), atlasTex: tex(gl.LINEAR),
  model: null, key: "", restarts: 0, contradictions: 0, doneAt: -1 });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution;
const rows = Math.max(4, Math.round(u.u_size)), cellPx = h / rows, cols = Math.ceil(w / cellPx);
const key = [u.u_tileset, rows, w, h].join("|");
const restart = () => {
  s.model.clear(); s.doneAt = -1; s.acc = 0; s.restarts++;
  s.collapsedAt.fill(-1); s.tileOf.fill(255);
};
if (key !== s.key) {
  // New tileset, size or canvas: redraw the atlas at the on-screen cell size and build a model.
  s.key = key;
  const set = s.buildSet(u.u_tileset, Math.max(8, Math.round(cellPx)));
  s.model = new s.wfc.SimpleTiledModel(set.data, null, cols, rows, false);
  s.model.initialize();
  Object.assign(s, { set, cols, rows, cells: new Uint8Array(cols * rows * 4), ghost: new Uint8Array(cols * rows * 64 * 4),
    collapsedAt: new Float32Array(cols * rows), tileOf: new Uint8Array(cols * rows), restarts: -1 });
  restart();
  gl.bindTexture(gl.TEXTURE_2D, s.atlasTex);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, set.atlas);
}
const m = s.model, N = s.cols * s.rows;
if (u.u_restart || (s.doneAt >= 0 && ctx.time - s.doneAt > u.u_hold)) restart();
// Observe + propagate, a few times a frame. A contradiction (rare with these sets) starts over.
if (s.doneAt < 0) {
  s.acc += u.u_speed;
  for (; s.acc >= 1; s.acc--) {
    if (!m.iterate(1)) { s.contradictions++; restart(); break; }
    if (m.isGenerationComplete()) { s.doneAt = ctx.time; s.acc = 0; break; }
  }
  m.graphics(s.ghost);
  gl.bindTexture(gl.TEXTURE_2D, s.ghostTex);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, s.cols * 8, s.rows * 8, 0, gl.RGBA, gl.UNSIGNED_BYTE, s.ghost);
}
let solved = 0;
for (let i = 0; i < N; i++) {
  if (m.sumsOfOnes[i] === 1) {
    if (s.collapsedAt[i] < 0) { s.collapsedAt[i] = ctx.time; s.tileOf[i] = m.wave[i].indexOf(true); }
    solved++;
  }
  const age = s.collapsedAt[i] < 0 ? 0 : ctx.time - s.collapsedAt[i];
  s.cells[i * 4] = s.tileOf[i];
  s.cells[i * 4 + 1] = Math.round(255 * Math.min(1, Math.max(0, m.entropies[i] / m.startingEntropy)));
  s.cells[i * 4 + 2] = Math.min(255, Math.round(age * 127.5));
}
gl.bindTexture(gl.TEXTURE_2D, s.cellTex);
gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, s.cols, s.rows, 0, gl.RGBA, gl.UNSIGNED_BYTE, s.cells);
gl.useProgram(s.prog);
ctx.utils.bindTexture(s.prog, "u_cells", s.cellTex, 0);
ctx.utils.bindTexture(s.prog, "u_ghost", s.ghostTex, 1);
ctx.utils.bindTexture(s.prog, "u_atlas", s.atlasTex, 2);
ctx.utils.drawFullscreen(s.prog, { u_grid: [s.cols, s.rows], u_origin: [(w - s.cols * cellPx) / 2, 0], u_cellPx: cellPx,
  u_atlasGrid: [s.set.atlasCols, s.set.atlasRows], u_res: [w, h], u_tint: s.set.tint, u_entropyOn: u.u_entropy ? 1 : 0 });
ctx.publish("solved", `${Math.round(solved / N * 100)}%`);
ctx.publish("tile variants", s.set.count);
ctx.publish("contradictions", s.contradictions);
